    var sourceLabel = state === 'saved' ? 'Last saved flight' : state === 'final' ? 'Current flight · Final' : state === 'paused' ? 'Current flight · Paused' : 'Current flight · Live';
    var context = [sourceLabel].concat(timing, conditions).join(' · ');
