    { key: 'heaterBees', logKey: 'hb', label: 'Heater bees', min: 0, max: 5000, step: 100, unit: 'bees' },
    { key: 'beesFanning', logKey: 'f', label: 'Fanning bees', min: 0, max: 500, step: 10, unit: 'bees' }
